package com.crm.invoice.service;
import com.crm.invoice.entity.*;import com.crm.invoice.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import jakarta.validation.constraints.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.math.BigDecimal;import java.util.*;
@Service @Transactional public class InvoiceFollowupService {private final InvoiceRepository invoices;private final InvoicePaymentRepository payments;private final ReminderPolicyRepository policies;private final ReminderTaskRepository tasks;private final InvoiceReminderRepository history;private final Clock clock;@jakarta.persistence.PersistenceContext private jakarta.persistence.EntityManager em;public InvoiceFollowupService(InvoiceRepository i,InvoicePaymentRepository p,ReminderPolicyRepository r,ReminderTaskRepository t,InvoiceReminderRepository h,Clock c){invoices=i;payments=p;policies=r;tasks=t;history=h;clock=c;}
 public record Policy(@NotNull Boolean enabled,@Min(0) @Max(365) int afterDays,@Min(1) @Max(365) int repeatDays,@NotBlank @Pattern(regexp="MANUAL|PHONE|EMAIL_RECORDED") String channel,@NotNull @Size(max=500) String message){}
 public record PolicyView(boolean enabled,long revision,int afterDays,int repeatDays,String channel,String message){}
 public record Due(String id,String number,String customerId,LocalDate dueDate,String currency,String total,String paid,String outstanding,boolean archived,String status,LocalDate nextReminder){}
 public record Task(String id,String invoiceId,long revision,LocalDate scheduledFor,String channel,String message,String state,String outcome){}
 @Transactional(readOnly=true) public PolicyView policy(){InvoiceWorkAccess.admin();return policyView(policies.findById(1L).orElseGet(ReminderPolicy::new));}
 public PolicyView configure(Policy input){InvoiceWorkAccess.admin();InvoiceWorkAccess.valid(input);var p=policies.lock().orElseGet(ReminderPolicy::new);tasks.cancelForPolicyChange();p.setEnabled(input.enabled());p.setAfterDays(input.afterDays());p.setRepeatDays(input.repeatDays());p.setChannel(input.channel());p.setMessage(input.message());p.setRevision(p.getRevision()+1);return policyView(policies.saveAndFlush(p));}
 @Transactional(readOnly=true) public Page<Due> invoices(LocalDate from,LocalDate to,String customer,String status,Boolean archived,String mode,int page){InvoiceWorkAccess.admin();range(from,to);if(customer!=null&&customer.length()>50||status!=null&&status.length()>50||!Set.of("ALL","UPCOMING","OVERDUE").contains(mode))throw new IllegalArgumentException("Invalid filters");var policy=policies.findById(1L).orElseGet(ReminderPolicy::new);LocalDate today=LocalDate.now(clock);Specification<Invoice> filter=(r,q,c)->{var conditions=new ArrayList<jakarta.persistence.criteria.Predicate>();conditions.add(c.between(r.get("dueDate"),from,to));if(customer!=null&&!customer.isBlank())conditions.add(c.equal(r.get("customerId"),customer));if(status!=null&&!status.isBlank())conditions.add(c.equal(r.get("status"),status));if(archived!=null)conditions.add(c.equal(r.get("archived"),archived));if(!mode.equals("ALL")){conditions.add(c.isFalse(r.get("archived")));conditions.add(r.get("status").in("PENDING","UNPAID","PARTIALLY_PAID"));conditions.add(mode.equals("OVERDUE")?c.lessThan(r.get("dueDate"),today):c.greaterThanOrEqualTo(r.get("dueDate"),today));}return c.and(conditions.toArray(jakarta.persistence.criteria.Predicate[]::new));};return invoices.findAll(filter,InvoiceWorkAccess.page(page)).map(r->{var paid=payments.sumForInvoice(r.getId());return new Due(r.getId().toString(),r.getInvoiceNumber(),r.getCustomerId(),r.getDueDate(),r.getCurrency(),r.getTotalAmount().toPlainString(),paid.toPlainString(),r.getTotalAmount().subtract(paid).toPlainString(),r.isArchived(),r.getStatus(),InvoiceLifecycle.reminders(r,paid)&&policy.isEnabled()?next(r,policy,today):null);});}
 public int prepare(int page){InvoiceWorkAccess.admin();var p=policies.lock().orElseGet(ReminderPolicy::new);if(!p.isEnabled())throw InvoiceWorkAccess.conflict();LocalDate today=LocalDate.now(clock);Specification<Invoice> filter=(r,q,c)->c.and(c.isFalse(r.get("archived")),r.get("status").in("PENDING","UNPAID","PARTIALLY_PAID"),c.lessThanOrEqualTo(r.get("dueDate"),today.minusDays(p.getAfterDays())));var batch=invoices.findAll(filter,PageRequest.of(page,20,Sort.by("id")));int created=0;for(var source:batch){var r=invoices.lockById(source.getId()).orElseThrow(InvoiceWorkAccess::missing);refresh(r);if(!InvoiceLifecycle.reminders(r,payments.sumForInvoice(r.getId())))continue;LocalDate first=r.getDueDate().plusDays(p.getAfterDays());if(today.isBefore(first))continue;long cycle=ChronoUnit.DAYS.between(first,today)/p.getRepeatDays();LocalDate slot=first.plusDays(cycle*p.getRepeatDays());if(tasks.existsByInvoiceIdAndPolicyRevisionAndScheduledFor(r.getId(),p.getRevision(),slot))continue;var task=new ReminderTask();task.setInvoiceId(r.getId());task.setPolicyRevision(p.getRevision());task.setScheduledFor(slot);task.setChannel(p.getChannel());task.setMessage(p.getMessage());tasks.saveAndFlush(task);created++;}return created;}
 @Transactional(readOnly=true) public Page<Task> tasks(String state,int page){InvoiceWorkAccess.admin();if(state!=null&&!Set.of("PREPARED","HANDLED","CANCELLED").contains(state))throw new IllegalArgumentException("Invalid reminder state");return tasks.list(state,InvoiceWorkAccess.page(page)).map(this::task);}
 public Task handle(long id,String notes){long actor=InvoiceWorkAccess.admin();if(notes==null||notes.isBlank()||notes.length()>500)throw new IllegalArgumentException("Describe the manual action");var t=tasks.findById(id).orElseThrow(InvoiceWorkAccess::missing);var r=invoices.lockById(t.getInvoiceId()).orElseThrow(InvoiceWorkAccess::missing);refresh(r);refresh(t);if(!t.getState().equals("PREPARED"))return task(t);var p=policies.findById(1L).orElseGet(ReminderPolicy::new);if(!p.isEnabled()||p.getRevision()!=t.getPolicyRevision()||!InvoiceLifecycle.reminders(r,payments.sumForInvoice(r.getId()))){t.setState("CANCELLED");t.setOutcome("Invoice or policy no longer eligible");return task(t);}var reminder=new InvoiceReminder();reminder.setInvoiceId(r.getId());reminder.setChannel(t.getChannel());reminder.setNotes(notes.trim());reminder.setRecordedBy(Long.toString(actor));history.saveAndFlush(reminder);t.setState("HANDLED");t.setOutcome(notes.trim());t.setHandledBy(actor);return task(t);}
 public void archive(long id){InvoiceWorkAccess.admin();var r=invoices.lockById(id).orElseThrow(InvoiceWorkAccess::missing);refresh(r);InvoiceLifecycle.archive(r,payments.sumForInvoice(id));tasks.cancelForInvoice(id);}
 private LocalDate next(Invoice r,ReminderPolicy p,LocalDate today){LocalDate first=r.getDueDate().plusDays(p.getAfterDays());if(today.isBefore(first))return first;long cycles=ChronoUnit.DAYS.between(first,today)/p.getRepeatDays();LocalDate slot=first.plusDays(cycles*p.getRepeatDays());return tasks.existsByInvoiceIdAndPolicyRevisionAndScheduledFor(r.getId(),p.getRevision(),slot)?slot.plusDays(p.getRepeatDays()):slot;}
 private void range(LocalDate from,LocalDate to){if(from==null||to==null||from.getYear()<1000||to.getYear()>9999||to.isBefore(from)||ChronoUnit.DAYS.between(from,to)>365)throw new IllegalArgumentException("At most 366 inclusive days");}
 private void refresh(Object row){if(em!=null)em.refresh(row,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);}private PolicyView policyView(ReminderPolicy p){return new PolicyView(p.isEnabled(),p.getRevision(),p.getAfterDays(),p.getRepeatDays(),p.getChannel(),p.getMessage());}private Task task(ReminderTask t){return new Task(t.getId().toString(),t.getInvoiceId().toString(),t.getPolicyRevision(),t.getScheduledFor(),t.getChannel(),t.getMessage(),t.getState(),t.getOutcome());}
}
